package com.gatecraft.game;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.graphics.RectF;
import java.util.Random;

final class MetalFighterView extends BaseArcadeView {
  private float px=210,ex=735,vx,evx,aiTimer,specialCd,hitFlash;
  private int php=100,ehp=100,score,round=1;
  private boolean left,right,block,punch,kick,arc;
  private int pAnim,eAnim;
  private final RectF lBtn=new RectF(22,430,118,520),rBtn=new RectF(128,430,224,520);
  private final RectF punchBtn=new RectF(610,430,692,520),kickBtn=new RectF(700,430,782,520),blockBtn=new RectF(790,430,872,520),arcBtn=new RectF(878,430,958,520);
  private final Random rnd=new Random(33);
  MetalFighterView(Context c,GateCraftGame o){super(c,o);}
  @Override public int score(){return score;}@Override public int level(){return round;}@Override public int lives(){return 1;}
  @Override public void restart(){px=210;ex=735;php=100;ehp=100;vx=evx=0;specialCd=0;hitFlash=0;left=right=block=punch=kick=arc=false;invalidate();}
  @Override void updateGame(float dt){specialCd=Math.max(0,specialCd-dt);hitFlash=Math.max(0,hitFlash-dt);float sp=280;if(left)vx=-sp;else if(right)vx=sp;else vx*=Math.pow(.001,dt);px+=vx*dt;px=Math.max(80,Math.min(820,px));aiTimer-=dt;if(aiTimer<=0){aiTimer=.28f+rnd.nextFloat()*.45f;float d=px-ex;if(Math.abs(d)>145)evx=(d>0?1:-1)*175;else{evx=0;if(rnd.nextFloat()<.62f)enemyStrike();}}ex+=evx*dt;ex=Math.max(120,Math.min(870,ex));if(Math.abs(px-ex)<76){if(px<ex){px=Math.min(px,ex-72);ex=Math.max(ex,px+72);}else{px=Math.max(px,ex+72);ex=Math.min(ex,px-72);}}if(punch){punch=false;playerStrike(12,92,1);}if(kick){kick=false;playerStrike(18,110,2);}if(arc){arc=false;if(specialCd<=0){specialCd=2.8f;playerStrike(30,230,3);}}if(ehp<=0){score+=1000;round++;owner.reportGameComplete(score);restart();}if(php<=0){owner.reportGameOver(score);score=Math.max(0,score-300);restart();}}
  private void playerStrike(int dmg,float range,int anim){pAnim=anim;if(Math.abs(px-ex)<=range){ehp-=dmg;ex+=(ex>px?1:-1)*18;hitFlash=.12f;score+=dmg*5;owner.reportScore(score);}}
  private void enemyStrike(){eAnim=1;if(Math.abs(px-ex)<110){int d=block?5:14;php-=d;px+=(px>ex?1:-1)*14;hitFlash=.10f;}}
  @Override void drawGame(Canvas c){fill(c,Color.rgb(24,18,30),0,0,960,540);fill(c,Color.rgb(70,39,86),0,72,960,250);for(int y=80;y<245;y+=18)fill(c,(y/18)%2==0?Color.rgb(81,47,93):Color.rgb(60,36,75),0,y,960,y+8);fill(c,Color.rgb(24,25,30),0,220,960,410);for(int x=0;x<960;x+=150){fill(c,Color.rgb(49,42,38),x,190,x+70,410);fill(c,Color.rgb(93,65,43),x+8,205,x+18,410);fill(c,Color.rgb(11,13,17),x+26,250,x+59,410);}line(c,Color.rgb(190,137,58),8,40,138,560,138);line(c,Color.rgb(190,137,58),7,560,138,770,208);line(c,Color.rgb(190,137,58),5,280,138,280,210);fill(c,Color.rgb(39,47,55),0,358,960,540);for(int y=360;y<540;y+=24)line(c,Color.rgb(25,31,37),2,0,y,960,y);for(int x=0;x<960;x+=48)line(c,Color.rgb(58,67,74),2,x,358,x+130,540);fill(c,Color.rgb(61,35,29),430,278,535,358);fill(c,Color.rgb(231,88,32),448,300,517,345);fill(c,Color.rgb(255,196,57),460,309,505,338);for(int i=0;i<14;i++){float sx=475+(i%5)*14,sy=292-(i*17%62);fill(c,i%2==0?Color.rgb(255,211,65):Color.rgb(237,103,35),sx,sy,sx+3,sy+5);}drawFighter(c,px,337,false,pAnim,(int)(System.currentTimeMillis()/100)%2);drawFighter(c,ex,337,true,eAnim,(int)(System.currentTimeMillis()/120)%2);fill(c,Color.rgb(8,8,12),0,0,960,74);text(c,"METAL FIGHTER",480,31,27,Color.rgb(244,209,80),Paint.Align.CENTER,true);text(c,t("LAKATOS SZAKI","METALWORKER","METALLBAUER","HERRERO","MÉTALLIER","金属工","FABBRO","SERRALHEIRO","ŚLUSARZ","METAALBEWERKER","LĂCĂTUȘ","СЛЕСАРЬ"),18,58,14,Color.WHITE,Paint.Align.LEFT,true);text(c,t("KÓKLER KONTÁR","HACK RIVAL","PFUSCHER","CHAPUCERO","BRICOLEUR","劣质工","PASTICCIONE","GAMBIARRA","PARTACZ","BEUNHAAS","CÂRPACI","ХАЛТУРЩИК"),942,58,14,Color.WHITE,Paint.Align.RIGHT,true);hpBar(c,18,10,php,Color.rgb(48,190,71),false);hpBar(c,662,10,ehp,Color.rgb(206,57,45),true);text(c,"R"+round,480,59,18,Color.WHITE,Paint.Align.CENTER,true);if(hitFlash>0){fill(c,Color.argb(80,255,230,150),0,74,960,410);}arcadeButton(c,lBtn,"◀",Color.rgb(46,95,152),left);arcadeButton(c,rBtn,"▶",Color.rgb(46,95,152),right);arcadeButton(c,punchBtn,t("ÜT","HIT","HIEB","GOLPE","COUP","拳","COLPO","SOCO","CIOS","SLAG","LOV","УДАР"),Color.rgb(163,60,43),false);arcadeButton(c,kickBtn,t("RÚG","KICK","TRITT","PATADA","PIED","踢","CALCIO","CHUTE","KOP","TRAP","PICIOR","ПИНОК"),Color.rgb(170,88,36),false);arcadeButton(c,blockBtn,t("VÉD","BLOCK","BLOCK","BLOQ","BLOC","防","PARA","DEF","BLOK","BLOK","BLOC","БЛОК"),Color.rgb(58,99,132),block);arcadeButton(c,arcBtn,specialCd<=0?t("ÍV","ARC","LICHT","ARCO","ARC","弧","ARCO","ARCO","ŁUK","BOOG","ARC","ДУГА"):"…",Color.rgb(112,64,152),false);}
  private void hpBar(Canvas c,float x,float y,int v,int col,boolean reverse){float w=280;fill(c,Color.rgb(40,35,31),x,y,x+w,y+18);float f=Math.max(0,v)/100f;if(reverse)fill(c,col,x+w-w*f+2,y+2,x+w-2,y+16);else fill(c,col,x+2,y+2,x+2+(w-4)*f,y+16);stroke(c,Color.rgb(234,220,170),2,x,y,x+w,y+18);}
  private void drawFighter(Canvas c,float x,float ground,boolean enemy,int anim,int bob){int skin=enemy?Color.rgb(194,145,101):Color.rgb(220,169,111);int shirt=enemy?Color.rgb(106,57,44):Color.rgb(44,103,151);int armor=enemy?Color.rgb(87,78,72):Color.rgb(89,96,106);float y=ground-118+bob*2;fill(c,Color.rgb(41,43,48),x-24,y+80,x-6,y+116);fill(c,Color.rgb(41,43,48),x+7,y+80,x+25,y+116);fill(c,Color.rgb(18,20,24),x-31,y+111,x-5,y+121);fill(c,Color.rgb(18,20,24),x+5,y+111,x+32,y+121);fill(c,shirt,x-31,y+35,x+31,y+86);fill(c,armor,x-25,y+39,x+25,y+58);fill(c,skin,x-15,y+8,x+16,y+38);fill(c,enemy?Color.rgb(96,31,28):Color.rgb(230,177,45),x-20,y+3,x+20,y+12);fill(c,Color.rgb(50,31,25),x-13,y+27,x+13,y+33);if(anim==1){fill(c,skin,x-44,y+42,x-28,y+58);fill(c,skin,x+28,y+40,x+54,y+55);fill(c,Color.rgb(195,198,201),x+50,y+43,x+92,y+49);}else if(anim==2){fill(c,skin,x-42,y+47,x-27,y+62);fill(c,skin,x+28,y+42,x+47,y+60);fill(c,Color.rgb(191,194,196),x+40,y+55,x+78,y+63);}else if(anim==3){fill(c,skin,x-40,y+43,x-27,y+60);fill(c,skin,x+28,y+42,x+50,y+58);line(c,Color.rgb(110,196,255),8,x+48,y+48,x+130,y+28);line(c,Color.WHITE,2,x+52,y+48,x+130,y+28);}else{fill(c,skin,x-43,y+42,x-28,y+69);fill(c,skin,x+28,y+42,x+43,y+69);fill(c,Color.rgb(196,199,202),x+40,y+62,x+71,y+67);}if(block){fill(c,Color.rgb(67,73,80),x-50,y+36,x-29,y+88);stroke(c,Color.rgb(205,205,195),2,x-50,y+36,x-29,y+88);}}
  @Override void onGameDown(float x,float y){left=in(lBtn,x,y);right=in(rBtn,x,y);if(in(blockBtn,x,y))block=true;if(in(punchBtn,x,y))punch=true;if(in(kickBtn,x,y))kick=true;if(in(arcBtn,x,y))arc=true;}@Override void onGameMove(float x,float y){left=in(lBtn,x,y);right=in(rBtn,x,y);block=in(blockBtn,x,y);}@Override void onGameUp(float x,float y){left=right=block=false;}
}
